/* gm_prologue.h - the PowerPC functions' stack prologues (gm_prologue.c, generated by
 * tools/gm_prologues.py), replayed by GM_FN (gm.h). */
#pragma once
#include <stdint.h>
typedef struct { uint32_t addr; uint16_t size, n; const int16_t *e; } gm_prologue_t;
/* e: n pairs (offset from the new stack pointer, what): 0x400 the LR, 0x100|r a GPR, 0x200|r an
   FPR (64 bits), 0x300|r a paired single (psq_st, GQR 0) */
extern const gm_prologue_t gm_prologues[];
extern const int gm_prologue_count;
